//! Oracle parser and comparison engine for the bitmap-brush stamp plan (L07-E).
//!
//! `fixtures/bitmap-brush-resources-stamp/oracle.txt` was generated by
//! `tools/gen_oracle.js` from baseline fbe4b8a3: the VERBATIM `seededRng` and
//! `bakeToCanvas` (`src/js/bitmap-brush.js`) run against the real Paper.js 0.12.18
//! in a Node `vm` with a recording canvas. Rows (`#` lines are provenance, hex
//! tokens are IEEE-754 binary64 big-endian, `~` is absent):
//! `R seed n d0..` RNG draws, `Q a b c count r0 r1` `Numerical.solveQuadratic`,
//! `C id size spacing scatter seed opacity pressure closed nseg nprof` bake input,
//! `G id x y hix hiy hox hoy` segment, `F id x y p` pressure sample,
//! `B id x y w h` `path.bounds`, `T id minX minY w h SCALE cw ch alpha` geometry,
//! `K id i x y jx jy s left top ps` stamp, `N id n` stamp count. Every comparison
//! is on the bit pattern, so a mutated `StampRules` or a corrupted row is noticed.

use super::{StampPath, StampPlan, StampPlanError, StampRules, StampSpec};
use crate::evaluation::object_scene_style_kernels::bitmap_brush_resources_stamp_bounds::{
    path_bounds, solve_quadratic,
};
use crate::evaluation::property_follow_path_sample::SegmentIn;

pub(crate) const ORACLE: &str = include_str!("fixtures/bitmap-brush-resources-stamp/oracle.txt");

pub(crate) fn f(token: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(token, 16).expect("f64 bits"))
}

pub(crate) fn same(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits()
}

fn handle(x: &str, y: &str) -> Option<[f64; 2]> {
    (x != "~").then(|| [f(x), f(y)])
}

/// Data rows of one tag, without the tag.
pub(crate) fn rows_in(text: &str, tag: char) -> Vec<&str> {
    text.lines()
        .filter(|line| line.starts_with(tag) && line[1..].starts_with(' '))
        .map(|line| &line[2..])
        .collect()
}

#[derive(Clone, Debug)]
pub(crate) struct ExpectedStamp {
    pub x: f64,
    pub y: f64,
    pub jx: f64,
    pub jy: f64,
    pub size: f64,
    pub left: f64,
    pub top: f64,
    pub ps: f64,
}

#[derive(Clone, Debug)]
pub(crate) struct Case {
    pub id: String,
    pub name: String,
    pub spec: StampSpec,
    pub closed: bool,
    pub segments: Vec<SegmentIn>,
    pub profile: Vec<[f64; 3]>,
    pub bounds: [f64; 4],
    pub rect: [f64; 4],
    pub scale: f64,
    pub pixels: (u32, u32),
    pub alpha: f64,
    pub count: usize,
    pub stamps: Vec<ExpectedStamp>,
}

pub(crate) fn cases_in(text: &str) -> Vec<Case> {
    let mut out: Vec<Case> = Vec::new();
    let mut name = String::new();
    for line in text.lines() {
        if let Some(rest) = line.strip_prefix("# case ") {
            name = rest.split_once(": ").map(|p| p.1).unwrap_or("").to_string();
            continue;
        }
        let t: Vec<&str> = line.split(' ').collect();
        match t[0] {
            "C" => out.push(Case {
                id: t[1].to_string(),
                name: name.clone(),
                spec: StampSpec {
                    size: f(t[2]),
                    spacing: f(t[3]),
                    scatter: f(t[4]),
                    seed: f(t[5]),
                    opacity: f(t[6]),
                    pressure: t[7] == "1",
                },
                closed: t[8] == "1",
                segments: Vec::new(),
                profile: Vec::new(),
                bounds: [0.0; 4],
                rect: [0.0; 4],
                scale: 0.0,
                pixels: (0, 0),
                alpha: 0.0,
                count: 0,
                stamps: Vec::new(),
            }),
            "G" => out.last_mut().expect("case").segments.push(SegmentIn {
                point: [f(t[2]), f(t[3])],
                handle_in: handle(t[4], t[5]),
                handle_out: handle(t[6], t[7]),
            }),
            "F" => out
                .last_mut()
                .expect("case")
                .profile
                .push([f(t[2]), f(t[3]), f(t[4])]),
            "B" => out.last_mut().expect("case").bounds = [f(t[2]), f(t[3]), f(t[4]), f(t[5])],
            "T" => {
                let case = out.last_mut().expect("case");
                case.rect = [f(t[2]), f(t[3]), f(t[4]), f(t[5])];
                case.scale = f(t[6]);
                case.pixels = (
                    t[7].parse().expect("canvas w"),
                    t[8].parse().expect("canvas h"),
                );
                case.alpha = f(t[9]);
            }
            "K" => out.last_mut().expect("case").stamps.push(ExpectedStamp {
                x: f(t[3]),
                y: f(t[4]),
                jx: f(t[5]),
                jy: f(t[6]),
                size: f(t[7]),
                left: f(t[8]),
                top: f(t[9]),
                ps: f(t[10]),
            }),
            "N" => out.last_mut().expect("case").count = t[2].parse().expect("count"),
            _ => {}
        }
    }
    out
}

pub(crate) fn cases() -> Vec<Case> {
    cases_in(ORACLE)
}

pub(crate) fn case_named(name: &str) -> Case {
    cases()
        .into_iter()
        .find(|c| c.name == name)
        .unwrap_or_else(|| panic!("no oracle case named {name}"))
}

pub(crate) fn plan_of(rules: &StampRules, case: &Case) -> Result<StampPlan, StampPlanError> {
    let path = StampPath {
        segments: &case.segments,
        closed: case.closed,
        pressure_profile: if case.profile.is_empty() {
            None
        } else {
            Some(case.profile.as_slice())
        },
    };
    rules.plan(&case.spec, &path)
}

/// Differences between the plan `rules` produce and the oracle's geometry and stamps.
pub(crate) fn plan_mismatches(rules: &StampRules, case: &Case) -> Vec<String> {
    let plan = match plan_of(rules, case) {
        Ok(plan) => plan,
        Err(error) => return vec![format!("case {}: {error:?}", case.id)],
    };
    let mut out = Vec::new();
    let r = plan.texture.rect;
    let got = [r.min_x, r.min_y, r.w, r.h];
    for (k, label) in ["minX", "minY", "w", "h"].iter().enumerate() {
        if !same(got[k], case.rect[k]) {
            out.push(format!("case {} {label}", case.id));
        }
    }
    if !same(plan.texture.scale, case.scale) {
        out.push(format!("case {} SCALE", case.id));
    }
    if (plan.texture.pixel_width, plan.texture.pixel_height) != case.pixels {
        out.push(format!("case {} canvas size", case.id));
    }
    if !same(plan.alpha, case.alpha) {
        out.push(format!("case {} alpha", case.id));
    }
    if plan.stamps.len() != case.count || case.count != case.stamps.len() {
        out.push(format!(
            "case {} stamp count {} want {}",
            case.id,
            plan.stamps.len(),
            case.count
        ));
        return out;
    }
    for (i, (s, e)) in plan.stamps.iter().zip(&case.stamps).enumerate() {
        let pairs = [
            (s.x, e.x, "x"),
            (s.y, e.y, "y"),
            (s.jitter_x, e.jx, "jx"),
            (s.jitter_y, e.jy, "jy"),
            (s.size, e.size, "size"),
            (s.left(), e.left, "left"),
            (s.top(), e.top, "top"),
            (s.ps, e.ps, "ps"),
        ];
        for (a, b, label) in pairs {
            if !same(a, b) {
                out.push(format!("case {} stamp {i} {label}", case.id));
            }
        }
    }
    out
}

pub(crate) fn plan_mismatches_all(rules: &StampRules, text: &str) -> Vec<String> {
    cases_in(text)
        .iter()
        .flat_map(|case| plan_mismatches(rules, case))
        .collect()
}

pub(crate) fn bounds_mismatches(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    for case in cases_in(text) {
        let b = path_bounds(&case.segments, case.closed);
        let got = [b.x, b.y, b.width, b.height];
        if got.iter().zip(&case.bounds).any(|(a, e)| !same(*a, *e)) {
            out.push(format!("case {} bounds", case.id));
        }
    }
    out
}

pub(crate) fn rng_mismatches(rules: &StampRules, text: &str) -> Vec<String> {
    let mut out = Vec::new();
    for row in rows_in(text, 'R') {
        let t: Vec<&str> = row.split(' ').collect();
        let mut rng = rules.rng(f(t[0]));
        let n: usize = t[1].parse().expect("draw count");
        for (k, token) in t[2..2 + n].iter().enumerate() {
            if !same(rng.next(), f(token)) {
                out.push(format!("seed {} draw {k}", t[0]));
            }
        }
    }
    out
}

pub(crate) fn quadratic_mismatches(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    for row in rows_in(text, 'Q') {
        let t: Vec<&str> = row.split(' ').collect();
        let (count, roots) = solve_quadratic(f(t[0]), f(t[1]), f(t[2]));
        let want: i32 = t[3].parse().expect("root count");
        if count != want {
            out.push(format!("Q {row}: count {count}"));
            continue;
        }
        for k in 0..usize::try_from(count.max(0)).expect("count") {
            if !same(roots[k], f(t[4 + k])) {
                out.push(format!("Q {row}: root {k}"));
            }
        }
    }
    out
}
